from difflib import SequenceMatcher
from intelligence.models import MatchResult
def compare_reports(left,right,**kwargs):
    same_type=1. if left.incident_type and left.incident_type==right.incident_type else 0.; location=1. if left.location_name and left.location_name==right.location_name else .35 if not left.location_name or not right.location_name else 0.; minutes=abs((left.event_time-right.event_time).total_seconds())/60 if left.event_time and right.event_time else 39.; time=max(0,1-minutes/60); a,b=set(left.keywords),set(right.keywords); semantic=.65*(len(a&b)/len(a|b) if a|b else 0)+.35*SequenceMatcher(None,left.description.lower(),right.description.lower()).ratio(); score=.3*semantic+.3*location+.2*time+.2*same_type; classification='duplicate' if score>=.9 else 'related' if score>=.65 and same_type else 'possible_match' if score>=.45 else 'unrelated'; reasons=[('same incident type' if same_type else 'different or unknown incident type'),f'text similarity {semantic:.2f}'];return MatchResult(left.report_id,right.report_id,round(score,3),classification,round(location,3),round(time,3),round(semantic,3),same_type,reasons)
